"""All overflow.h macros/functions including constant-vs-runtime edge cases."""
def register(topic,q,detail):
 def lesson(title,symbol,why,principle,use,reading,qa,cards):
  topic(title,'라이브러리·알고리즘','include/linux/overflow.h',symbol,why,principle,use,reading,*(q(*x) for x in qa),details=[detail(*x) for x in cards])
 lesson('정수 형식의 표현 경계·signed 부호 비트를 피한 최대값','__type_half_max',
  '숫자형의 최대·최소를 구할 때 signed shift 자체가 잘못된 연산이 되지 않게 하는 원리를 배웁니다.',
  '__type_half_max는 형식 크기와 is_signed_type에 따라 1의 이동 위치를 선택합니다. signed는 부호 비트보다 한 자리 아래에서 시작하고 두 half를 더해 최대값을 만듭니다. type_max와 type_min은 typeof를 통해 형식 또는 변수 표현에 대응합니다. 최소는 -max-1 변환으로 만들며 _Bool의 0·1도 과도한 cast가 고려합니다.',
  '지원 정수형의 표현 범위를 검증할 때 type_min(int),type_max(unsigned int)처럼 사용합니다. Linux의 8비트 바이트와 정수형 모델을 전제로 읽고 부호 비트에 signed 1을 직접 shift하는 대안의 정의 범위를 확인합니다.',
  '__type_half_max·__type_max·type_max·__type_min·type_min을 함께 읽으세요.',
  [('signed 8비트 정수의 최소·최대는?','-128과 127이다','-127과 128이다','두의 보수 범위에서 음수 쪽이 하나 더 큽니다. 최대값과 -max-1의 관계를 읽습니다.'),('signed 최대값 계산에서 부호 비트 직접 shift를 피하는 이유는?','그 중간 signed 연산의 정의되지 않은 동작을 피하기 위해서다','항상 최대값을 0으로 만들기 위해서다','원본 주석은 보기 쉬운 대안 식이 중간 단계에서 undefined behavior와 컴파일 경고를 만들 수 있다고 설명합니다.')],
  [('Bool','_Bool은 저장 크기와 별개로 값 0·1을 갖습니다. 최대·최소의 cast 정책과 overflow builtin이 _Bool* 출력은 허용하지 않는 조건을 구분합니다.'),('범위 기술','이 helper는 수치 범위 상수를 제공합니다. 이후 산술을 자동으로 넓은 형식으로 바꾸는 장치가 아닙니다.')])
 lesson('부호 검사 매크로·unsigned 경고를 피하는 두 조건','is_non_negative',
  'signed와 unsigned 입력에 같은 부호 검사 표현을 사용하는 전처리기 기술을 배웁니다.',
  'is_non_negative(a)는 a>0||a==0이고 is_negative는 그 부정입니다. unsigned a<0의 항상 거짓 경고를 피하기 위한 표현입니다. a는 두 번 등장하며 단락 평가에 따라 한 번 또는 두 번 값 평가될 수 있습니다. 부호 검사와 인수의 부작용 안전성은 별도입니다.',
  '오버플로 shift 검사 등의 임시에 저장된 값을 검사합니다. a++ 같은 인수는 먼저 지역 값으로 고정하고 boolean 비교를 숫자 범위 전체 검증으로 읽지 않습니다.',
  '두 비교와 ||의 단락 평가를 읽으세요.',
  [('unsigned 0의 is_non_negative 결과는?','true다','unsigned이므로 0만 false다','a>0은 거짓이지만 a==0이 참입니다. 0도 비음수 범위에 포함합니다.'),('인수 a++를 직접 넣으면 항상 한 번 평가되는가?','아니며 두 비교의 평가 경로를 확인해야 한다','||가 자동으로 임시 변수를 만든다','단락 평가와 한 번 값 보관은 다릅니다. 원본 식은 a를 두 곳에서 사용합니다.')],
  [('음수','signed -1은 두 비교가 모두 거짓이라 is_negative가 참입니다.'),('경고 회피','-Wtype-limits 회피가 목적입니다. 숫자값의 표현 폭이나 다른 산술 overflow 검사를 대체하지 않습니다.')])
 lesson('오버플로 반환 확인 강제·must_check inline wrapper','__must_check_overflow',
  '오버플로 결과를 계산해 놓고 무시하는 호출을 컴파일 진단으로 찾는 기술을 배웁니다.',
  '__must_check_overflow는 bool을 받아 unlikely(overflow)를 반환하는 __must_check inline 함수입니다. check_* 매크로는 이 helper를 통해 형식 일반성을 유지하며 반환을 확인하도록 진단 속성을 붙입니다. unlikely는 분기 예상 힌트이고 overflow 발생을 없애거나 오류 처리를 자동 실행하지 않습니다.',
  'if(check_add_overflow(a,b,&result))처럼 boolean을 실제 처리합니다. true이면 result가 이미 저장됐더라도 안전한 크기·인덱스로 사용하지 않고 해당 실패 경로를 선택합니다.',
  '__must_check 속성과 반환 unlikely를 읽으세요.',
  [('must_check 경고가 대신 하는 역할은?','반환 결과를 무시한 사용을 진단하는 것이다','실행 중 모든 호출을 자동 종료하는 것이다','컴파일 진단 속성과 runtime 오류 처리 코드를 구분합니다. 호출자가 boolean에 따른 정책을 작성합니다.'),('unlikely가 overflow를 false로 바꾸는가?','아니며 원래 bool을 유지한다','예상하지 않는 사건이면 결과를 강제로 false로 만든다','분기 예상 힌트는 조건 의미를 바꾸지 않습니다. 오류를 드물게 예상해도 실제 true 결과를 처리해야 합니다.')],
  [('속성 지원','진단 세부와 오류 취급 여부는 컴파일러·빌드 옵션에 연결됩니다. 형식·값 검사를 무시해도 안전해지는 장치가 아닙니다.'),('공통 연결','add·sub·mul·shift와 runtime 형식 적합성 helper가 같은 반환 확인 경로에 연결됩니다.')])
 lesson('검사된 덧셈·출력 형식의 overflow와 결과 저장','check_add_overflow',
  '더한 수학 결과가 출력 변수 형식에 들어가는지 동시에 검사하는 방법을 배웁니다.',
  'check_add_overflow는 __builtin_add_overflow(a,b,d)를 감쌉니다. builtin은 수학적 합이 출력 *d 형식에 표현되는지 판정하고 시도한 변환 결과도 *d에 기록합니다. 입력과 출력 형식이 다를 수 있어 검사 기준은 단순히 입력 둘의 폭이 아닙니다. true는 overflow, false는 유효한 표현입니다.',
  '유효한 출력 포인터와 원하는 결과형으로 호출하고 반환을 먼저 검사합니다. 예를 들어 unsigned char 출력에서 250+10은 표현되지 않아 true이며 출력에 작은 wrap 결과가 있어도 할당 크기로 사용하지 않습니다.',
  'builtin 인수·출력 포인터와 true 의미를 읽으세요.',
  [('8비트 unsigned 출력에 250+10을 검사하면?','overflow true이며 시도 결과도 저장된다','결과가 작아지므로 정상 false다','260은 0..255에 들어가지 않습니다. 결과 저장과 유효 판정은 별도입니다.'),('입력보다 좁은 출력형을 사용하면 검사 기준은?','그 출력형에 수학적 결과가 들어가는지다','항상 입력형 두 개의 가장 넓은 폭만 본다','builtin은 d가 가리키는 결과형을 기준으로 표현 가능성을 판단합니다.')],
  [('정의된 검사','signed overflow를 먼저 일반 +로 실행한 뒤 검사하는 코드가 아닙니다. builtin에 원래 피연산자를 전달합니다.'),('오류 정책','helper는 boolean과 출력만 제공합니다. errno·메모리 할당 실패 정책은 caller가 결정합니다.')])
 lesson('검사된 뺄셈·unsigned underflow도 오류 조건','check_sub_overflow',
  'unsigned 숫자라도 필요한 수학 차이가 음수면 표현 실패로 검사하는 방법을 배웁니다.',
  'check_sub_overflow는 __builtin_sub_overflow(a,b,d)의 boolean을 must_check로 감쌉니다. unsigned 출력에서 3-5의 수학 차이 -2는 표현되지 않아 true입니다. 언어상 일반 unsigned subtraction의 wrap과 원하는 크기 계산의 유효성을 구분합니다.',
  '남은 용량·범위 차이를 계산할 때 boolean을 처리하고 유효 결과만 사용합니다. signed 출력의 양끝 차이 역시 해당 출력형 표현 가능성으로 검사하며 포인터 유효성을 준비합니다.',
  'sub builtin과 결과 저장 설명을 읽으세요.',
  [('unsigned 출력에 3-5의 검사 결과는?','true다','unsigned wrap은 항상 정상 false다','수학 차이 -2가 출력 unsigned에 들어가지 않으므로 overflow 검사는 true입니다.'),('overflow true에서 출력 숫자를 바로 남은 크기로 쓰는가?','아니며 실패 경로를 처리한다','이미 저장됐으므로 무조건 유효한 크기다','시도한 변환 결과가 기록되어도 안전한 크기라는 보장은 아닙니다. 검사 boolean을 먼저 사용합니다.')],
  [('부호','signed 차이도 출력의 최소·최대 범위로 판단합니다. 단순히 a<b라는 조건 하나로 모든 mixed형 검사 규약을 대체하지 않습니다.'),('wrapper','반환 확인이 요구되는 check_* 계열입니다. 의도적인 wrapping_sub와 목적이 다릅니다.')])
 lesson('검사된 곱셈·원소 수와 원소 크기','check_mul_overflow',
  '원소 개수와 크기의 곱이 작게 wrap되어 과소 할당되는 문제를 배웁니다.',
  'check_mul_overflow는 __builtin_mul_overflow를 사용해 결과형 표현 실패를 검출합니다. 일반 count*size가 먼저 좁은 형식에서 wrap된 뒤 helper에 넘어가면 이미 잃은 수학 결과를 복원할 수 없습니다. 원래 두 인수를 builtin에 전달해야 합니다.',
  'size_t bytes를 출력으로 두고 check_mul_overflow(count,element_size,&bytes)의 boolean을 확인합니다. count·size 입력 변환과 결과폭을 명확히 하고 성공 시에만 할당을 진행합니다.',
  '곱을 미리 계산하지 않는 builtin 호출을 읽으세요.',
  [('먼저 좁은 count*size를 계산해 wrap된 뒤 검사하면?','이미 잃은 값을 일반적으로 복원할 수 없다','builtin이 원래 수학 곱을 항상 추측한다','검사할 피연산자를 원래 값으로 전달해야 합니다. 앞선 overflow의 결과만 전달하면 그 결과를 기준으로 계산합니다.'),('check_mul_overflow의 false는?','곱이 출력형에 표현 가능함을 뜻한다','메모리 할당까지 이미 성공했다는 뜻이다','산술 유효성과 allocator 성공은 다른 단계입니다. helper는 메모리를 할당하지 않습니다.')],
  [('0','유효 출력 포인터에서 곱 인수 하나가 0이면 수학 결과 0이 표현됩니다. 오류 sentinel의 sticky 전파와는 다른 산술 의미입니다.'),('크기 정책','SIZE_MAX 포화가 필요하면 size_mul처럼 별도 정책 wrapper를 사용할 수 있습니다.')])
 lesson('의도적인 wrap 산술·원하는 결과형으로 add·sub·mul','wrapping_add',
  'overflow를 거절할 대신 의도적으로 형식 폭 안의 순환 결과를 얻는 API를 배웁니다.',
  'wrapping_add·sub·mul은 명시한 type의 임시 __val을 만들고 해당 overflow builtin의 boolean을 버린 뒤 결과를 반환합니다. 일반 signed overflow 연산을 직접 수행해 UB로 만든 뒤 wrap을 가정하는 방식이 아닙니다. 입력의 수학 결과를 해당 폭으로 변환한 값을 의도적으로 사용합니다.',
  '순환 인덱스·정의된 폭 연산처럼 wrap 의미가 필요한 곳에 type을 명시합니다. 메모리 크기나 검증이 필요한 외부 입력을 무조건 wrap API로 처리하지 않으며 별도 동기화가 필요한 공유 변수의 atomic 연산으로 읽지 않습니다.',
  '세 매크로의 builtin과 무시하는 boolean을 읽으세요.',
  [('wrapping_add(unsigned char,250,10)의 8비트 결과는?','4다','260을 무한 폭으로 유지한다','260을 8비트 unsigned 결과형으로 변환하면 4입니다. 이 API는 그 순환 결과를 의도적으로 반환합니다.'),('이 wrapping API가 공유 변수 atomic 갱신을 제공하는가?','아니며 산술 결과 의미와 동기화는 별도다','builtin을 썼으므로 모든 CPU 갱신이 자동 atomic이다','산술 overflow builtin과 atomic memory operation은 다른 기술입니다.')],
  [('signed wrap','signed 형식에서도 builtin의 결과 저장 규약을 사용합니다. 일반 signed a+b의 UB를 켜 둔 코드와 다릅니다.'),('sanitizer','주석은 의도적인 wrap이 wrap-around sanitizer를 불필요하게 울리지 않게 하는 목적을 설명합니다. 잘못된 lifetime·포인터 문제까지 숨겨주는 API는 아닙니다.')])
 lesson('wrap 대입 wrapper·lvalue 주소를 한 번 얻기','wrapping_assign_add',
  '복잡한 lvalue를 반복 평가하지 않고 의도적인 순환 대입을 수행하는 방법을 배웁니다.',
  'wrapping_assign_add와 sub는 typeof(var)* __ptr=&var로 주소를 얻고 *ptr를 해당 형식의 wrapping 결과로 대입합니다. statement expression 마지막 대입 값이 반환됩니다. var의 주소 식을 한 번 얻는 구조이며 read-modify-write 자체는 atomic이 아닙니다.',
  '수정 가능한 lvalue에 사용하고 배열 인덱스 증가 같은 주소 식 평가를 추적합니다. const·주소를 취할 수 없는 bitfield나 별도 동기화가 필요한 공유 상태에는 조건을 검토합니다.',
  '주소 임시·원래 값 읽기·대입 반환을 읽으세요.',
  [('a[i++]에 assign wrapper를 적용하면 핵심 주소 평가 구조는?','lvalue 주소를 한 번 보관한다','var를 세 번 독립 확장해 인덱스를 세 번 늘린다','원본은 &var를 __ptr에 저장해 읽기와 쓰기에 재사용합니다.'),('wrapping_assign_sub가 반환하는 값은?','대입된 새 값이다','항상 overflow boolean이다','마지막 식은 *ptr=wrapping_sub(...)입니다. check_* API의 boolean 반환과 다릅니다.')],
  [('원자성','주소 보관은 평가 횟수 문제를 해결합니다. CPU 간 원자적 갱신이나 IRQ 동기화는 별도로 설계합니다.'),('lvalue 조건','typeof(var) 포인터를 선언하고 &var를 얻으므로 일반 숫자 rvalue를 수정하는 API가 아닙니다.')])
 lesson('검사된 왼쪽 이동·출력 폭과 되돌림 비교','check_shl_overflow',
  '비트 이동 뒤 사라진 비트나 signed 부호 변화까지 검사하는 원리를 배웁니다.',
  'check_shl_overflow는 a,s,d를 각각 임시에 저장하고 a를 unsigned long long으로 옮깁니다. 유효한 이동량만 선택해 출력에 shift 결과를 저장한 뒤 다시 오른쪽 이동해 원래 a와 같은지 확인합니다. 출력 음수·입력 음수·이동량 대체 여부도 실패 조건입니다. 계산 임시는 ULL이므로 지원 입력·출력 폭과 이동량을 함께 확인합니다.',
  '일반적인 최대 64비트 정수 출력과 유효 포인터에서 검사하고 true의 출력은 안전한 값으로 사용하지 않습니다. 128비트 출력에 64 이상 이동을 ULL 계산으로 확장해 보장하지 않습니다.',
  '_a_full·_to_shift·역이동 비교를 읽으세요.',
  [('8비트 unsigned 출력에서 128<<1을 검사하면?','비트 손실로 true다','최종 0이므로 안전 false다','변환 후 다시 오른쪽 이동해 원래 128을 얻을 수 없습니다. 손실된 비트를 검사합니다.'),('signed 출력의 부호 비트가 켜지면?','음수 출력 조건으로 true다','표현 범위와 상관없이 항상 유효하다','이 API는 sign bit 설정도 안전하지 않은 이동 조건으로 검사합니다.')],
  [('한 번 평가','a,s,d를 지역 임시에 저장합니다. 출력 폭 sizeof(*d)는 일반 정수 포인터의 값 평가가 아니라 형식 크기 관찰입니다.'),('계산 폭','실제 shift 피연산자는 unsigned long long입니다. 결과 포인터를 임의로 넓혔다고 내부 이동 폭이 자동으로 커지는 것은 아닙니다.')])
 lesson('잘못된 이동량·음수 입력과 실패 출력','check_shl_overflow',
  'invalid shift를 직접 실행하지 않고 실패로 표시하는 안전 경계와 결과 사용 금지를 배웁니다.',
  's가 nonnegative이고 출력 비트 폭보다 작을 때만 _to_shift=s로 선택하며 그렇지 않으면 0으로 대체합니다. 그 뒤 _to_shift!=s를 실패로 반환합니다. 음수 a도 실패입니다. 유효한 계산폭 안에서 invalid s를 0으로 대신했다는 구현 관찰이 원래 요청의 안전한 결과를 의미하지 않습니다.',
  '음수·폭 이상 이동량에서 true를 처리하고 출력 숫자를 인덱스·크기로 사용하지 않습니다. 결과가 저장된다는 contract와 실패 시 safe for use가 아니라는 원본 경고를 함께 읽습니다.',
  'invalid s의 대체 0과 마지막 실패 조건을 읽으세요.',
  [('a=5,s=-1 요청의 출력 숫자를 안전 결과로 쓰는가?','아니며 true 실패를 먼저 처리한다','대체 이동량 0이니까 원래 요청도 정상이다','대체는 잘못된 shift 실행을 피하는 내부 장치입니다. 요청 의미가 유효해진다는 뜻이 아닙니다.'),('입력 a가 음수면 이 shift 검사 정책은?','실패 true다','음수도 항상 sign 확장으로 유효하다','원본 실패 조건에 is_negative(_a)가 있습니다. 일반 부호 있는 shift 의미와 다른 안전 검사 정책입니다.')],
  [('출력 저장','실패에서도 시도 결과가 저장됩니다. 다른 check_*처럼 저장 여부와 안전 판정은 별도입니다.'),('폭 조건','출력 폭 검사와 내부 ULL shift 폭을 모두 지켜야 합니다. 일반적 커널 정수 폭을 넘어선 사용을 무제한 지원으로 가정하지 않습니다.')])
 lesson('다른 형식에 저장 가능성·상수와 runtime 검사','overflows_type',
  '값이 다른 폭·부호 형식에 안전하게 들어가는지 별도 산술 없이 검사하는 방법을 배웁니다.',
  'overflows_type은 __is_constexpr로 상수식을 판정합니다. 상수 분기는 source·destination의 signed 여부에 맞는 최소·최대 비교이고 runtime은 목적 typeof(T)의 임시0에 check_add_overflow(x,0,&v)를 사용합니다. 상수 입력의 결과도 상수 표현으로 사용할 수 있습니다.',
  'overflows_type(256,u8)처럼 저장 형식을 점검하고 음수→unsigned 변환도 실패로 확인합니다. T는 형식 또는 목적 변수로 지정합니다. runtime 값에 필요한 검사를 단순 cast 후 비교로 대체하지 않습니다.',
  '__overflows_type_constexpr·__overflows_type·choose_expr를 읽으세요.',
  [('256을 8비트 unsigned에 저장 가능한가?','아니며 overflows_type은 true다','cast가 가능하니 항상 false다','C에서 변환 문법이 가능한 것과 원래 값이 손실 없이 표현되는 것은 다릅니다.'),('runtime 목적 형식 검사의 핵심은?','목적형 임시0과 builtin checked add다','먼저 좁게 cast해서 사라진 값을 무조건 무시한다','수학 x+0이 목적형에 표현되는지 checked builtin으로 판정합니다.')],
  [('부호','상수 음수의 unsigned 목적형 저장은 비교 분기에 의해 overflow입니다. 값 손실 없는 표현 여부가 목표입니다.'),('상수성','__is_constexpr와 일반 __builtin_constant_p는 구분합니다. 함수 scope에서는 상수 static assert로 쓸 수 있지만 파일 scope에서는 선택되지 않은 runtime statement expression도 문법 검사되어 거절될 수 있습니다. 상수 결과와 모든 선언 위치의 문법 허용은 다른 조건입니다.')])
 lesson('cast 가능한 상수·runtime에서는 같은 형식만','castable_to_type',
  '범위에 들어가는 리터럴을 허용하면서 runtime 변수는 형식 일치를 요구하는 API를 배웁니다.',
  'castable_to_type은 상수이면 !__overflows_type_constexpr로 값의 표현 가능성을 검사합니다. runtime이면 __same_type(n,T)를 사용하므로 현재 숫자가 작아도 다른 형식은 false일 수 있습니다. overflows_type의 runtime 값 범위 검사와 다른 목적입니다.',
  '제네릭 매크로 인수의 형식 계약에 사용합니다. int 변수값7과 상수7이 목적 u8에서 다른 결과가 될 수 있음을 설명하고 동적 변환의 범위검사가 필요하면 overflows_type을 선택합니다.',
  '상수 분기와 __same_type fallback을 읽으세요.',
  [('int runtime 변수값7을 u8과 castable 검사하면?','형식이 달라 false일 수 있다','값7이므로 반드시 true다','runtime 경로는 값 범위가 아니라 형식 호환성을 봅니다. 상수 리터럴 허용 정책과 다른 분기입니다.'),('상수7을 u8에 castable 검사하면?','범위 안이라 true다','형식이 int라 항상 false다','상수 분기는 목적형 범위에 들어가는 리터럴을 허용합니다.')],
  [('계약','castable이라는 이름을 모든 동적 숫자의 범위 검사로 확대하지 않습니다. 실제 choose_expr 분기를 읽습니다.'),('형식 도구','__same_type은 GNU 형식 호환 builtin에 연결됩니다. 포인터로 데이터를 변환·복사하는 runtime 함수가 아닙니다.')])
 lesson('크기 곱의 포화·SIZE_MAX와 0의 조합','size_mul',
  '할당 크기 곱이 overflow이면 최대 sentinel을 반환하는 정책과 조합 경계를 배웁니다.',
  'size_mul은 두 size_t 인수를 check_mul_overflow하고 실패하면 SIZE_MAX, 아니면 곱을 반환합니다. 입력이 함수 인수로 먼저 size_t에 변환됩니다. SIZE_MAX*0은 산술 결과0이라 overflow가 없어 0입니다. SIZE_MAX가 모든 후속 곱에서 무조건 전파되는 sticky 오류값은 아닙니다.',
  '결과도 size_t에 저장하고 SIZE_MAX 처리와 실제 allocator 실패를 관리합니다. 음수 signed 입력을 size_t로 보내기 전 유효성을 확인하며 포화 결과와 합법적으로 최대인 결과를 값만으로 구분할 수 없음을 고려합니다.',
  'checked product와 두 반환, factor0을 대입해 읽으세요.',
  [('size_mul(SIZE_MAX,0)의 실제 결과는?','0이다','sentinel이므로 반드시 SIZE_MAX다','원본은 builtin 곱 검사입니다. 수학 곱0은 표현 가능해 0을 반환합니다.'),('이 포화 helper의 결과를 작은 unsigned 형식에 저장해도 되는가?','size_t 결과 폭을 유지해 손실을 피해야 한다','SIZE_MAX가 어느 형식에서도 같은 sentinel이다','주석은 lvalue도 size_t여야 한다고 설명합니다. 좁은 형식 변환이 sentinel과 실제 크기를 바꿀 수 있습니다.')],
  [('입력 변환','인수형은 size_t입니다. 음수나 더 넓은 값이 앞선 변환에서 바뀌면 원래 수학 값 전체의 검사로 읽지 않습니다.'),('오류와 최대값','성공한 정확한 SIZE_MAX와 overflow 포화 SIZE_MAX가 같은 숫자입니다. 호출 정책은 이 구분 제한을 고려합니다.')])
 lesson('크기 합의 포화·헤더와 payload 계산','size_add',
  '헤더 크기와 payload를 더할 때 작게 wrap되는 과소 할당을 막는 정책을 배웁니다.',
  'size_add는 size_t 덧셈을 checked builtin으로 수행해 overflow이면 SIZE_MAX를 반환합니다. 정상 합이 최대값과 같은 경우도 SIZE_MAX입니다. 실제 메모리 할당은 이 함수 밖에서 수행되고 함수 결과가 최대값이라고 가능한 메모리 크기를 보장하지 않습니다.',
  'header bytes와 payload bytes의 단위를 맞추고 size_t에 결과를 저장합니다. 입력 변환 전에 음수·손실 값을 검사하며 결과에 맞는 실패 처리를 allocator와 연결합니다.',
  'check_add_overflow와 반환 경로를 읽으세요.',
  [('SIZE_MAX-2에 4를 size_add하면?','SIZE_MAX로 포화한다','일반 wrap 결과1을 정상 크기로 반환한다','수학 합이 size_t 범위를 넘으므로 포화 sentinel을 반환합니다.'),('size_add의 성공은 메모리 확보 성공인가?','아니며 산술 크기 계산만 한다','helper 안에서 항상 allocator를 호출한다','이 본문은 숫자만 계산합니다. 할당 성공과 생명주기는 별도 단계입니다.')],
  [('합의 단위','바이트 합 계산에서는 두 입력이 모두 바이트여야 합니다. 요소 개수와 바이트를 그대로 더해도 helper가 단위를 검출하지 않습니다.'),('조합','size_mul로 payload를 구하고 size_add로 헤더를 더할 수 있습니다. sentinel과 0 곱의 비고정 전파도 함께 읽습니다.')])
 lesson('크기 차의 포화·두 SIZE_MAX 인수는 별도 거절','size_sub',
  '크기 뺄셈이 underflow뿐 아니라 이전 포화값도 거절하는 특별 정책을 배웁니다.',
  'size_sub는 minuend나 subtrahend가 SIZE_MAX이면 계산 전 SIZE_MAX를 반환합니다. 그 외 checked subtraction이 underflow면 SIZE_MAX, 아니면 차이를 반환합니다. 따라서 SIZE_MAX-SIZE_MAX의 수학0도 이 함수에서는 포화값으로 남깁니다.',
  'size_add·mul과 조합한 크기 차에서 sentinel을 지우지 않는 정책을 사용합니다. 합법적인 최대 크기 인수도 별도 거절되는 점과 size_mul의 0 조합 차이를 확인합니다.',
  '두 sentinel 검사와 builtin 조건의 ||를 읽으세요.',
  [('size_sub(SIZE_MAX,SIZE_MAX)의 반환은?','SIZE_MAX다','항상 수학 차이0이다','이 helper는 두 인수 중 하나가 sentinel이면 먼저 포화 반환합니다.'),('size_sub(3,5)의 결과는?','SIZE_MAX다','wrap된 큰 차이를 정상 반환한다','checked unsigned 차이가 underflow이므로 오류 포화 정책을 적용합니다.')],
  [('정책 차이','size_sub는 명시적 sentinel 인수 검사를 합니다. size_mul에는 같은 검사 분기가 없습니다.'),('자료형','두 인수·결과는 size_t입니다. 결과를 좁은 변수에 저장해 sentinel을 잃지 않게 합니다.')])
 lesson('두·세 차원 배열 크기·중간 포화와 마지막 0','array3_size',
  '다중 곱을 작은 중간값으로 wrap하지 않고 계산하되 포화 조합의 예외를 배웁니다.',
  'array_size(a,b)는 size_mul(a,b), array3_size는 size_mul(size_mul(a,b),c)입니다. 각각의 곱은 size_t 포화 검사를 합니다. 다만 첫 곱이 SIZE_MAX로 포화된 뒤 c=0이면 두 번째 곱은0을 반환합니다. 모든 조합을 sticky sentinel이라고 설명하면 실제 동작과 다릅니다.',
  '실제 차원·원소 크기를 숫자 의미에 맞게 넣고 전체 크기 해석을 확인합니다. overflow 입력을 부적절한 0 차원과 조합해 기존 실패를 감추는지 검토하며 결과형 size_t를 유지합니다.',
  '두 wrapper와 중첩 size_mul을 읽으세요.',
  [('array3_size(SIZE_MAX,2,0)의 실제 결과는?','첫 곱은 포화하고 마지막0곱으로 결과0이다','모든 경로에서 SIZE_MAX가 고정된다','size_mul은 SIZE_MAX*0을0으로 계산합니다. 중간 포화값의 조합 정책을 실제 함수로 확인합니다.'),('array_size가 입력 차원의 단위를 자동 아는가?','아니며 숫자 곱만 계산한다','항상 원소형 sizeof까지 자동 곱한다','인수 의미와 바이트 환산은 caller가 정합니다. helper가 임의 원소형을 추론하는 API가 아닙니다.')],
  [('계산 단계','두 곱을 한 일반 a*b*c 식으로 먼저 계산하지 않습니다. 각 단계에 checked size_mul이 있습니다.'),('0 차원','정상 empty 배열의0크기와 이전 잘못된 범위의 포화가0으로 사라지는 조합을 요구에 맞게 구분합니다.')])
 lesson('가변 배열 payload 크기·상수 분기의 일반 곱','flex_array_size',
  '가변 길이 멤버의 크기를 구하는 매크로가 상수와 runtime에서 다른 검사 경로를 쓰는 점을 배웁니다.',
  'flex_array_size는 count가 정수 상수식이면 count*sizeof(member element)+__must_be_array를 일반 상수식으로 계산합니다. runtime count이면 size_mul로 계산합니다. __must_be_array는 pointer를 배열로 잘못 전달하는 형식을 진단합니다. 상수 경로는 별도 checked multiply가 아니므로 너무 큰 상수의 wrap도 자동 포화로 일반 보장하지 않습니다.',
  '지원 가능한 상수 count 또는 검증한 동적 count를 사용하고 원소 크기를 포함한 payload 바이트를 얻습니다. member가 실제 배열인지 확인하며 음수 count와 결과폭을 관리합니다.',
  'choose_expr와 상수 곱/runtime size_mul 차이를 읽으세요.',
  [('runtime count의 payload 곱 경로는?','size_mul의 포화 검사다','모든 입력을 무조건 일반 곱으로만 계산한다','정수 상수식 여부에 따라 분기를 선택합니다. runtime은 checked size_mul을 사용합니다.'),('상수 count 경로도 항상 overflow에서 SIZE_MAX인가?','아니며 원본 상수식의 형식·범위를 확인한다','상수이면 자동으로 arbitrary precision 저장이다','상수 분기는 일반 곱입니다. 포화 함수 경로와 다른 실제 식을 읽어야 합니다.')],
  [('sizeof','멤버 원소형 크기를 구하는 식은 실제 p 포인터를 역참조해 값을 읽지 않습니다. 유효한 선언 형식이 중요합니다.'),('pointer 거절','배열 여부 검사는 숫자 count 범위나 실제 할당 길이 검증을 대체하지 않습니다.')])
 lesson('구조체와 가변 꼬리 크기·형식 기반 NULL 표현','struct_size',
  '고정 헤더와 가변 배열을 함께 담을 저장 크기를 계산하고 상수 경계 차이를 배웁니다.',
  'struct_size는 sizeof(*p)와 flex_array_size를 더합니다. 상수 count는 일반 상수 덧셈, runtime은 size_add입니다. struct_size_t(type,member,count)는 (type*)NULL을 전달해 선언 형식으로 계산합니다. sizeof 안의 형식 관찰이므로 이 NULL을 실제 데이터 읽기 포인터로 역참조하는 것이 아닙니다.',
  '가능하면 실제 인스턴스 포인터와 struct_size를 연결해 원소형을 맞춥니다. 매우 큰 상수의 곱·합 wrap와 동적 포화 경로를 구분하고 sizeof 헤더의 padding까지 포함된다는 점을 확인합니다.',
  'sizeof·상수합/runtime합·struct_size_t 연결을 읽으세요.',
  [('struct_size_t가 NULL을 넘겨도 가능한 이유는?','sizeof와 멤버 원소형 관찰에 쓰기 때문이다','런타임 NULL 역참조를 반드시 실행하기 때문이다','형식 크기 계산과 실제 데이터 읽기를 구분합니다. 여기서는 선언형으로 저장 크기를 얻습니다.'),('struct_size의 상수 count에서 합 경로는?','일반 상수 덧셈이며 범위를 확인한다','언제나 size_add의 runtime 포화다','choose_expr의 두 경로가 다릅니다. 상수 초기화 지원과 runtime overflow 검사 정책을 함께 읽습니다.')],
  [('padding','sizeof 구조체에는 정렬 padding이 포함됩니다. 필드 바이트 합만으로 헤더 크기를 추정하지 않습니다.'),('권장 연결','주석은 type-only helper보다 실제 인스턴스 기반 struct_size를 선호한다고 설명합니다. 타입과 변수의 연결을 유지하는 용도입니다.')])
 lesson('스택 가변 꼬리 저장·union과 상수 count 요구','_DEFINE_FLEX',
  '동적 크기 구조체를 제한된 상수 길이로 스택에 놓는 union 기반 기술을 배웁니다.',
  '_DEFINE_FLEX는 __builtin_constant_p(count)의 static assert와 union을 만듭니다. union 안의 u8 bytes[struct_size_t(...)]가 필요한 저장 크기를 확보하고 type obj가 정렬·객체 형식을 제공합니다. name##_u 토큰 이름과 그 union을 가리키는 type* name을 선언합니다. DEFINE_RAW_FLEX는 initializer={}로 zero 초기화합니다.',
  '컴파일 시 고정되고 충분히 작은 count를 사용해 스택 수명을 지킵니다. 이 매크로는 heap allocation이나 임의 runtime VLA가 아니며 큰 상수는 스택 사용량 문제를 만듭니다. 원소·헤더 크기의 상수 표현 범위도 먼저 확인합니다.',
  'static assert·union bytes/obj·이름결합·pointer 선언을 읽으세요.',
  [('이 저장의 생명주기는?','선언된 스택 scope의 객체 수명이다','항상 heap에 할당돼 함수 반환 뒤 영구 유지된다','매크로는 union 지역 저장을 선언합니다. 포인터 반환이나 scope 밖 보관은 수명 문제를 일으킬 수 있습니다.'),('DEFINE_RAW_FLEX의 초기화 정책은?','zero 초기화다','항상 초기값 없이 쓰레기 데이터를 둔다','wrapper는 ={} initializer를 전달합니다. 내부 helper가 별도 initializer를 받을 수 있는 구조와 구분합니다.')],
  [('정렬','union의 obj 멤버가 구조체 정렬을 반영합니다. bytes 배열의 길이와 실제 union sizeof의 정렬 padding도 다를 수 있습니다.'),('객체 크기 조회','__struct_size(name)는 compiler_types의 object-size builtin에 연결됩니다. 단순 sizeof(pointer)와 달리 알려진 pointed storage의 크기를 관찰합니다.')])
 lesson('counted 가변 배열 선언·카운터 필드 초기화','DEFINE_FLEX',
  '가변 배열의 길이 필드를 같은 상수 count로 초기화하는 wrapper의 역할을 배웁니다.',
  'DEFINE_FLEX는 _DEFINE_FLEX의 initializer로 .obj.COUNTER=COUNT를 전달합니다. 나머지 저장은 zero 초기화되고 배열 길이 메타데이터 필드를 지정한 count로 맞춥니다. __counted_by 같은 annotation의 의미와 지원은 구조체 선언·컴파일러에 연결되며 wrapper가 모든 접근을 runtime 검사하는 코드를 직접 생성하지 않습니다.',
  '유효한 구조체·멤버·counter 필드와 지원 상수 count를 제공하고 원소 접근은 실제 확보한 count 안에서 수행합니다. 카운터 필드를 이후 임의로 늘려 저장 크기까지 늘어난 것으로 읽지 않습니다.',
  'initializer의 .obj.COUNTER와 내부 union 저장을 읽으세요.',
  [('COUNT=4의 COUNTER 필드 초기값은?','4다','zero wrapper라 무조건0이다','DEFINE_FLEX는 지정 필드에 count를 설정합니다. RAW_FLEX의 전체 zero 초기화와 차이입니다.'),('counter 필드를 4에서100으로 쓰면 저장도 자동 확장되는가?','아니며 실제 union 저장 크기는 고정이다','annotation이 stack 공간을 runtime 자동 늘린다','메타데이터 변경과 물리 저장 확장은 다른 작업입니다. 스택 union의 크기는 선언 시 결정됩니다.')],
  [('진단 지원','annotation을 지원하는 도구chain의 경계 진단과 wrapper의 숫자 초기화를 구분합니다. 지원 없는 모델에서 전체 컴파일러 보호를 검증했다고 주장하지 않습니다.'),('헤더 전체','형식 경계·부호·must_check·checked add/sub/mul/shift·wrapping/assign·형식 적합성·size 포화·배열/flexible/struct 크기·스택 flex 선언을 스무 수업에서 모두 연결합니다.')])
